import{I as o,o as r,c as l,b6 as t,J as p,w as h,j as a,a as s}from"./chunks/framework.COUcLbTA.js";const m=JSON.parse('{"title":"Use Jobs to Be Done to Find What Users Really Want to Get Done","description":"A beginner-friendly introduction to Jobs to Be Done. Learn how to turn a vague idea into a clearer user scenario, a sharper need, and a more grounded MVP direction.","frontmatter":{"title":"Use Jobs to Be Done to Find What Users Really Want to Get Done","description":"A beginner-friendly introduction to Jobs to Be Done. Learn how to turn a vague idea into a clearer user scenario, a sharper need, and a more grounded MVP direction."},"headers":[],"relativePath":"en/stage-1/appendix-jobs-to-be-done/index.md","filePath":"en/stage-1/appendix-jobs-to-be-done/index.md"}'),u={name:"en/stage-1/appendix-jobs-to-be-done/index.md"},b=Object.assign(u,{setup(d){const n="About <strong>1.5 hours</strong>";return(c,e)=>{const i=o("ChapterIntroduction");return r(),l("div",null,[e[1]||(e[1]=t('<h1 id="use-jobs-to-be-done-to-find-what-users-really-want-to-get-done" tabindex="-1">Use Jobs to Be Done to Find What Users Really Want to Get Done <a class="header-anchor" href="#use-jobs-to-be-done-to-find-what-users-really-want-to-get-done" aria-label="Permalink to “Use Jobs to Be Done to Find What Users Really Want to Get Done”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2>',3)),p(i,{duration:n,tags:["JTBD","User Needs","Product Thinking","Discovery"],coreOutput:"1 JTBD statement that feels closer to a real user need",expectedOutput:"Turn a vague idea into a clearer user scenario and a more grounded MVP direction"},{default:h(()=>[...e[0]||(e[0]=[a("p",null,"Many beginners start product thinking from the wrong place: features. You see another product with AI summaries, tags, agents, or workflows, and your first instinct is to ask, “What features should I add too?”",-1),a("p",null,"But users rarely choose a product because a feature name sounds cool. Most of the time, they are trying to make progress in a specific situation, and they temporarily “hire” a tool to help them move forward.",-1),a("p",null,[s("That is the core reminder behind "),a("strong",null,"Jobs to Be Done (JTBD)"),s(": users are not buying features. They are hiring a solution to help them make progress.")],-1),a("p",null,"This article explains JTBD in plain language and turns it into something you can actually use when shaping an AI product.",-1)])]),_:1}),e[2]||(e[2]=t(`<div class="info custom-block"><p class="custom-block-title">Minimal SOP</p><p><strong>Goal</strong>: After this, you should be better at turning a vague idea into a real user need instead of just a pile of feature names.</p><p><strong>Action</strong>: Write one rough product idea, talk to 3 possible users about the last time they dealt with this problem, then rewrite it as one JTBD sentence.</p><p><strong>Result</strong>: You will leave with a clearer need hypothesis and a better sense of what your first version should solve.</p><p><strong>Quick links</strong>: <a href="#jtbd-what">What JTBD is</a> · <a href="#jtbd-formula">One-sentence formula</a> · <a href="#jtbd-ai">How AI can help</a></p></div><h2 id="what-you-will-learn" tabindex="-1">What You Will Learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to “What You Will Learn”">​</a></h2><ol><li>What Jobs to Be Done means in plain language</li><li>How to separate “what users say they want” from “what they are really trying to get done”</li><li>How to turn a vague idea into a situation, trigger, progress, workaround, and success condition</li><li>How JTBD connects to AI product thinking, interviews, and prompt-based analysis</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-what-jobs-to-be-done-means" tabindex="-1"><a href="#top-jtbd">1. What Jobs to Be Done Means</a> <a class="header-anchor" href="#_1-what-jobs-to-be-done-means" aria-label="Permalink to “1. What Jobs to Be Done Means”">​</a></h2><p>Jobs to Be Done, often shortened to <strong>JTBD</strong>, is built around a simple idea: users “hire” a product to get something done.</p><p>That “something” is usually not just a surface task. It is a kind of <strong>progress</strong>.</p><p>Examples:</p><ul><li>Not “I want an AI meeting-note tool,” but “I want to turn a messy meeting into a clear summary with owners and next steps before I forget everything.”</li><li>Not “I want a budgeting app,” but “I want to stop feeling anxious at the end of the month because I finally understand where my money went.”</li><li>Not “I want a resume optimizer,” but “I want to feel confident enough to send my application instead of endlessly tweaking my resume.”</li></ul><p>JTBD helps you focus less on feature names and more on what users are trying to move toward.</p><p>It also changes how you see competition. If the job is “make a long PDF easier to understand,” your competition is not just another AI tool. It may be a colleague, an intern, manual skimming, or even delaying the task.</p><h2 id="_2-jtbd-vs-personas-and-feature-lists" tabindex="-1">2. JTBD vs Personas and Feature Lists <a class="header-anchor" href="#_2-jtbd-vs-personas-and-feature-lists" aria-label="Permalink to “2. JTBD vs Personas and Feature Lists”">​</a></h2><p>Many beginners start by writing personas: 25 years old, white-collar worker, likes productivity tools, willing to try new apps. That information is not useless, but it usually does <strong>not explain why someone acts right now</strong>.</p><p>JTBD pushes you toward more useful questions:</p><ul><li>What situation triggered action?</li><li>What problem felt urgent?</li><li>What are they trying to move toward?</li><li>What clumsy workaround are they using now?</li><li>What result would make them say “this actually helped”?</li></ul><p>That is the difference:</p><ul><li>a persona tells you roughly who the person is</li><li>JTBD tells you what they are trying to get done right now</li></ul><p>Feature lists have a similar trap. Users may ask for export, rewrite, voice input, or smart tags. Those are surface requests. JTBD asks what sits underneath them:</p><ul><li>Why export to Word instead of PDF?</li><li>Why rewrite: because the tone is weak, or because it must fit a different audience?</li><li>Why voice input: because typing is annoying, or because they usually capture thoughts while walking, commuting, or leaving meetings?</li></ul><p>Sometimes a feature is just a temporary translation of a deeper job.</p><h2 id="_3-a-beginner-friendly-example" tabindex="-1">3. A Beginner-Friendly Example <a class="header-anchor" href="#_3-a-beginner-friendly-example" aria-label="Permalink to “3. A Beginner-Friendly Example”">​</a></h2><p>Imagine someone buys coffee and a sandwich every morning on the way to work.</p><p>On the surface, they are buying breakfast. In JTBD terms, they may really be trying to:</p><ul><li>solve breakfast with as little mental effort as possible</li><li>avoid being hungry before arriving at work</li><li>keep their morning routine moving without disruption</li></ul><p>The thing they &quot;hire&quot; is not really one specific sandwich brand. It is a reliable way to keep the morning moving.</p><p>The same logic applies to AI products. If you want to build an AI meeting summary tool, JTBD helps you step back from feature brainstorming and ask:</p><ul><li>What moment actually hurts?</li><li>What are users trying to make happen after the meeting?</li><li>What would make the output feel trustworthy enough to share?</li></ul><p>If the job becomes clear, priorities become clearer too. Maybe the first version does not need twelve export formats. Maybe it mainly needs:</p><ul><li>a clear structure</li><li>stable action-item extraction</li><li>easy sharing</li><li>output good enough to forward without embarrassment</li></ul><p>That is JTBD at its best: it brings you back from “which capabilities should I stack?” to “what progress am I helping the user make?”</p><h2 id="_4-a-practical-jtbd-template" tabindex="-1">4. A Practical JTBD Template <a class="header-anchor" href="#_4-a-practical-jtbd-template" aria-label="Permalink to “4. A Practical JTBD Template”">​</a></h2><p>If you are a beginner, do not overcomplicate this. Start with five parts.</p><h3 id="_4-1-situation" tabindex="-1">4.1 Situation <a class="header-anchor" href="#_4-1-situation" aria-label="Permalink to “4.1 Situation”">​</a></h3><p>In what moment or context does the user look for help?</p><ul><li>right after a meeting</li><li>late at night before submitting a resume</li><li>when the boss suddenly asks for a document</li><li>at the end of the month when money feels tight</li></ul><p>If you cannot describe the situation, the need is probably still too vague.</p><h3 id="_4-2-trigger" tabindex="-1">4.2 Trigger <a class="header-anchor" href="#_4-2-trigger" aria-label="Permalink to “4.2 Trigger”">​</a></h3><p>What makes them act now?</p><ul><li>a long document they do not know how to start reading</li><li>a deadline tomorrow and messy material today</li><li>a progress question from a manager that exposed their confusion</li><li>repeated friction in a manual workflow</li></ul><p>Triggers often come with emotion. That emotion matters.</p><h3 id="_4-3-progress" tabindex="-1">4.3 Progress <a class="header-anchor" href="#_4-3-progress" aria-label="Permalink to “4.3 Progress”">​</a></h3><p>What state are they trying to move toward?</p><ul><li>from chaos to clarity</li><li>from anxiety to confidence</li><li>from delay to action</li><li>from friction to flow</li><li>from vague output to something they can actually deliver</li></ul><p>Many people are not really buying tools. They are buying <strong>state change</strong>.</p><h3 id="_4-4-current-workaround" tabindex="-1">4.4 Current workaround <a class="header-anchor" href="#_4-4-current-workaround" aria-label="Permalink to “4.4 Current workaround”">​</a></h3><p>What are they doing right now without your product?</p><ul><li>copy-pasting manually</li><li>using Excel or Notes to hold things together</li><li>asking a colleague</li><li>procrastinating</li><li>bouncing between multiple tools</li></ul><p>The workaround is often your real competition.</p><h3 id="_4-5-success-condition" tabindex="-1">4.5 Success condition <a class="header-anchor" href="#_4-5-success-condition" aria-label="Permalink to “4.5 Success condition”">​</a></h3><p>What would make the user say this was truly helpful?</p><ul><li>getting a shareable result within 10 minutes</li><li>not needing a second major rewrite</li><li>making fewer mistakes</li><li>immediately knowing what to do next</li></ul><p>If you cannot say what “useful enough” means, the direction is probably still not focused enough.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-a-one-sentence-formula-you-can-reuse" tabindex="-1"><a href="#top-jtbd">5. A One-Sentence Formula You Can Reuse</a> <a class="header-anchor" href="#_5-a-one-sentence-formula-you-can-reuse" aria-label="Permalink to “5. A One-Sentence Formula You Can Reuse”">​</a></h2><p>Use this sentence pattern:</p><blockquote><p>When __________, I want to __________, so that I can __________.<br> Right now, I have to __________.</p></blockquote><p>Example:</p><blockquote><p>When I am preparing to apply for internships, I want to quickly turn my existing resume into a version that fits a specific role, so that I can submit applications without getting stuck in endless revisions.<br> Right now, I have to rewrite things manually and ask friends for feedback.</p></blockquote><p>That is already much more useful than “I want to build a resume AI.”</p><h2 id="_6-three-layers-of-a-job-in-ai-products" tabindex="-1">6. Three Layers of a Job in AI Products <a class="header-anchor" href="#_6-three-layers-of-a-job-in-ai-products" aria-label="Permalink to “6. Three Layers of a Job in AI Products”">​</a></h2><p>Many AI products look powerful in demos but fail to keep users. A common reason is that they solve only the surface task, not the deeper job.</p><p>You can roughly look at a job in three layers:</p><h3 id="_6-1-functional-layer" tabindex="-1">6.1 Functional layer <a class="header-anchor" href="#_6-1-functional-layer" aria-label="Permalink to “6.1 Functional layer”">​</a></h3><p>What is the surface task?</p><ul><li>summarize a document</li><li>rewrite text</li><li>extract action items</li><li>generate an image</li></ul><p>This is the easiest layer for users to say out loud.</p><h3 id="_6-2-emotional-layer" tabindex="-1">6.2 Emotional layer <a class="header-anchor" href="#_6-2-emotional-layer" aria-label="Permalink to “6.2 Emotional layer”">​</a></h3><p>What discomfort do they want to reduce, or what feeling do they want to gain?</p><ul><li>less panic</li><li>less embarrassment</li><li>less “starting from zero”</li><li>more confidence</li><li>more control</li></ul><p>Willingness to pay often has a lot to do with this layer.</p><h3 id="_6-3-social-layer" tabindex="-1">6.3 Social layer <a class="header-anchor" href="#_6-3-social-layer" aria-label="Permalink to “6.3 Social layer”">​</a></h3><p>Who do they want to look like in front of others?</p><ul><li>more reliable</li><li>more organized</li><li>more professional</li><li>more capable</li></ul><p>If you only solve the functional layer, you are easier to replace. If you understand the emotional and social layers too, your product direction often becomes much stronger.</p><h2 id="_7-use-jtbd-to-filter-product-directions" tabindex="-1">7. Use JTBD to Filter Product Directions <a class="header-anchor" href="#_7-use-jtbd-to-filter-product-directions" aria-label="Permalink to “7. Use JTBD to Filter Product Directions”">​</a></h2><p>Sometimes you do not already have a product. You have three to five ideas and do not know which one deserves attention. JTBD is useful here too.</p><p>Ask each idea:</p><ol><li>Is the situation concrete enough?</li><li>Are users already using some clumsy workaround?</li><li>Is the job painful enough or frequent enough?</li><li>If I solved it well, would users clearly feel a better state?</li><li>Can version one focus on just one important step in the job?</li></ol><p>If an idea still sounds like “kind of interesting” after this, but you cannot explain the trigger, workaround, or success condition, it is probably still a vague idea rather than a good starting direction.</p><h2 id="_8-interview-questions-you-can-use-right-away" tabindex="-1">8. Interview Questions You Can Use Right Away <a class="header-anchor" href="#_8-interview-questions-you-can-use-right-away" aria-label="Permalink to “8. Interview Questions You Can Use Right Away”">​</a></h2><p>Many people run interviews by asking: “What features do you want?” That usually gets surface answers.</p><p>JTBD-style questions are better:</p><ul><li>When was the last time this problem happened to you?</li><li>What were you doing at the time?</li><li>Why did you get stuck?</li><li>How did you solve it?</li><li>What part felt slow, frustrating, or risky?</li><li>If a tool helped, what result would make you say it was actually useful?</li><li>What alternatives have you tried, and why were they not good enough?</li></ul><p>These questions pull the conversation back into real experience instead of imagined preference.</p><h2 id="_9-use-ai-to-help-you-break-down-jtbd" tabindex="-1">9. Use AI to Help You Break Down JTBD <a class="header-anchor" href="#_9-use-ai-to-help-you-break-down-jtbd" aria-label="Permalink to “9. Use AI to Help You Break Down JTBD”">​</a></h2><p>JTBD is not an AI invention, but AI is very useful for organizing and clarifying JTBD.</p><p>For example, if you already collected 5 to 10 user quotes, you can ask AI to summarize them like this:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please act as a product research assistant.</span></span>
<span class="line"><span>I will give you raw user quotes.</span></span>
<span class="line"><span>Do not give feature ideas yet.</span></span>
<span class="line"><span>First organize them using Jobs to Be Done:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. What situation is the user in?</span></span>
<span class="line"><span>2. What event triggered action?</span></span>
<span class="line"><span>3. What progress are they really trying to make?</span></span>
<span class="line"><span>4. What is the current workaround?</span></span>
<span class="line"><span>5. What success condition matters most?</span></span>
<span class="line"><span>6. What emotional words show up repeatedly?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then turn the result into 3 JTBD hypotheses worth validating first.</span></span></code></pre></div><p>If you already have an idea, you can also use AI to do the first pass of narrowing:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build [your product idea].</span></span>
<span class="line"><span>Do not give me a feature list yet.</span></span>
<span class="line"><span>Use Jobs to Be Done to help me analyze:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. What concrete situations this product might serve</span></span>
<span class="line"><span>2. What core job exists in each situation</span></span>
<span class="line"><span>3. What alternatives already exist</span></span>
<span class="line"><span>4. Which job is the best starting point for an MVP, and why</span></span>
<span class="line"><span>5. Write the final recommendation as one clear JTBD sentence</span></span></code></pre></div><p>This helps prevent the classic AI trap: jumping straight to “brainstorm 50 features” before the direction is clear.</p><h2 id="_10-four-common-beginner-mistakes" tabindex="-1">10. Four Common Beginner Mistakes <a class="header-anchor" href="#_10-four-common-beginner-mistakes" aria-label="Permalink to “10. Four Common Beginner Mistakes”">​</a></h2><h3 id="_10-1-writing-the-job-as-a-feature" tabindex="-1">10.1 Writing the job as a feature <a class="header-anchor" href="#_10-1-writing-the-job-as-a-feature" aria-label="Permalink to “10.1 Writing the job as a feature”">​</a></h3><p>“AI summary,” “smart classification,” and “auto generation” are not jobs. They are possible solutions.</p><h3 id="_10-2-making-the-audience-too-broad" tabindex="-1">10.2 Making the audience too broad <a class="header-anchor" href="#_10-2-making-the-audience-too-broad" aria-label="Permalink to “10.2 Making the audience too broad”">​</a></h3><p>“All professionals,” “all students,” and “all founders” are usually too wide. The wider it is, the harder it becomes to see a real situation.</p><h3 id="_10-3-listening-only-to-what-users-say" tabindex="-1">10.3 Listening only to what users say <a class="header-anchor" href="#_10-3-listening-only-to-what-users-say" aria-label="Permalink to “10.3 Listening only to what users say”">​</a></h3><p>What people say matters, but their current workaround often reveals their priorities better.</p><h3 id="_10-4-trying-to-build-the-full-platform-too-early" tabindex="-1">10.4 Trying to build the full platform too early <a class="header-anchor" href="#_10-4-trying-to-build-the-full-platform-too-early" aria-label="Permalink to “10.4 Trying to build the full platform too early”">​</a></h3><p>JTBD works best when you focus on one important step in one concrete situation and make that part feel much better.</p><h2 id="_11-summary" tabindex="-1">11. Summary <a class="header-anchor" href="#_11-summary" aria-label="Permalink to “11. Summary”">​</a></h2><p>The real value of JTBD is not the label. It is the shift in perspective:</p><ul><li>stop looking first at features</li><li>start looking at the progress users are trying to make</li></ul><p>If you keep asking:</p><ul><li>In what situation does the user hire this?</li><li>What exactly are they stuck on?</li><li>What workaround are they using now?</li><li>What would “better” look like for them?</li></ul><p>your idea usually becomes much sharper.</p><p>It also helps you avoid one of the biggest mistakes in AI products: falling in love with capability demos instead of user progress.</p><p><a id="jtbd-ai"></a></p><h2 id="_12-how-ai-can-help-you-practice-jtbd" tabindex="-1"><a href="#top-jtbd">12. How AI Can Help You Practice JTBD</a> <a class="header-anchor" href="#_12-how-ai-can-help-you-practice-jtbd" aria-label="Permalink to “12. How AI Can Help You Practice JTBD”">​</a></h2><p>JTBD is not an AI invention, but AI can be a very helpful research assistant, organizer, and challenger. The key is this:</p><p><strong>use AI to organize and expand your thinking, not to invent user truth for you.</strong></p><h3 id="_12-1-turn-a-vague-idea-into-candidate-jtbd-statements" tabindex="-1">12.1 Turn a vague idea into candidate JTBD statements <a class="header-anchor" href="#_12-1-turn-a-vague-idea-into-candidate-jtbd-statements" aria-label="Permalink to “12.1 Turn a vague idea into candidate JTBD statements”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I currently have a vague product idea: [your idea].</span></span>
<span class="line"><span>Do not give me a feature list yet.</span></span>
<span class="line"><span>Use Jobs to Be Done to help me analyze:</span></span>
<span class="line"><span>1. What situations might this idea fit?</span></span>
<span class="line"><span>2. What progress might users want in each situation?</span></span>
<span class="line"><span>3. What current alternatives might they be using?</span></span>
<span class="line"><span>4. Which job feels best as an MVP starting point?</span></span>
<span class="line"><span>Write each job as one clear JTBD sentence.</span></span></code></pre></div><p>You can also write a very beginner-style input like this:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build something that helps college students find internships.</span></span>
<span class="line"><span>I can&#39;t explain it clearly yet.</span></span>
<span class="line"><span>Help me figure out what users might actually be trying to get done.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Possible JTBD directions:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. When I start internship applications, I want to know what I need to prepare first,</span></span>
<span class="line"><span>so I do not keep delaying because everything feels confusing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. When I see a job post, I want to quickly judge whether it is worth applying to,</span></span>
<span class="line"><span>so I do not waste energy on poor-fit roles.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. When I am ready to apply, I want to adapt my resume to a specific role,</span></span>
<span class="line"><span>so I can submit faster and feel more confident.</span></span></code></pre></div><p>The value here is that AI helps split one fuzzy idea into several clearer directions.</p><h3 id="_12-2-organize-raw-interview-notes" tabindex="-1">12.2 Organize raw interview notes <a class="header-anchor" href="#_12-2-organize-raw-interview-notes" aria-label="Permalink to “12.2 Organize raw interview notes”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Below are raw notes from 5 user interviews.</span></span>
<span class="line"><span>Do not suggest solutions yet.</span></span>
<span class="line"><span>First organize them using JTBD:</span></span>
<span class="line"><span>1. What situation is the user in?</span></span>
<span class="line"><span>2. What event triggered action?</span></span>
<span class="line"><span>3. What progress are they trying to make?</span></span>
<span class="line"><span>4. What is the current workaround?</span></span>
<span class="line"><span>5. What success condition matters most?</span></span>
<span class="line"><span>6. What patterns repeat across users?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Then summarize 3 JTBD hypotheses worth validating first.</span></span></code></pre></div><p>A very simple beginner input can look like this:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I asked 3 people and they roughly said:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Every time I apply for internships, I have to redo my resume and it&#39;s annoying.</span></span>
<span class="line"><span>2. I mostly worry that I still don&#39;t know if it&#39;s good enough.</span></span>
<span class="line"><span>3. Right now I ask seniors for help, but I don&#39;t want to bother them too often.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please help me summarize the real job they are trying to get done.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Organized result:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- common situation: preparing internship applications</span></span>
<span class="line"><span>- common pain: uncertainty about whether the resume is ready enough</span></span>
<span class="line"><span>- current workaround: asking seniors, revising manually</span></span>
<span class="line"><span>- possible JTBD:</span></span>
<span class="line"><span>  When I am preparing to apply, I want to know whether my resume is ready enough to send,</span></span>
<span class="line"><span>  so I stop getting stuck in endless revisions.</span></span></code></pre></div><p>This is useful because it turns messy quotes into something closer to a real need.</p><h3 id="_12-3-do-light-web-research-before-interviews" tabindex="-1">12.3 Do light web research before interviews <a class="header-anchor" href="#_12-3-do-light-web-research-before-interviews" aria-label="Permalink to “12.3 Do light web research before interviews”">​</a></h3><p>Before larger interview work, AI can help you do a light scan of outside information:</p><ul><li>how people complain about this problem in public communities</li><li>what existing tools mostly solve</li><li>what common workarounds people use</li><li>what users praise or dislike in current solutions</li></ul><p>This does not replace real user interviews, but it is a good warm-up for the Discover phase.</p><p>Simple input:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please look up common pain points students mention when editing resumes and applying for internships.</span></span>
<span class="line"><span>Focus on forums, public communities, and real user complaints.</span></span>
<span class="line"><span>Summarize the top 5 patterns.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Top recurring pain points:</span></span>
<span class="line"><span>1. Not knowing what to include</span></span>
<span class="line"><span>2. Not knowing how to tailor a resume for different roles</span></span>
<span class="line"><span>3. Feeling unsure whether the resume is good enough</span></span>
<span class="line"><span>4. Lack of reliable feedback</span></span>
<span class="line"><span>5. Delaying applications because the process feels heavy</span></span></code></pre></div><p>This kind of output is not final truth, but it helps you start interviews with a better map.</p><h3 id="_12-4-ask-ai-to-play-the-critic" tabindex="-1">12.4 Ask AI to play the critic <a class="header-anchor" href="#_12-4-ask-ai-to-play-the-critic" aria-label="Permalink to “12.4 Ask AI to play the critic”">​</a></h3><p>Sometimes we get emotionally attached to our own ideas. AI can help by acting as a strict critic:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Act as a very strict product research advisor.</span></span>
<span class="line"><span>Here is my JTBD hypothesis: [your hypothesis]</span></span>
<span class="line"><span>Critique it from these angles:</span></span>
<span class="line"><span>1. Is the situation still too broad?</span></span>
<span class="line"><span>2. Is this actually a feature, not a progress statement?</span></span>
<span class="line"><span>3. Are the alternatives too weak?</span></span>
<span class="line"><span>4. Is the success condition too vague?</span></span>
<span class="line"><span>5. What risk most needs validation?</span></span></code></pre></div><p>That kind of challenge helps you see whether you are really looking at user needs or just defending your favorite solution.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><ol><li>Pick one product idea and rewrite it into one JTBD sentence</li><li>Add the five parts: situation, trigger, progress, workaround, success condition</li><li>Talk to 3 potential users about the last time they faced this problem</li><li>Give the interview notes to AI and ask it to summarize 3 possible JTBD hypotheses</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,142))])}}});export{m as __pageData,b as default};
